"""
MAVLink Command Sender for WebGCS
Handles sending commands to drone (ARM, DISARM, TAKEOFF, etc.)

File size: Must stay under 150 lines per WebGCS PRD
"""
import time
from typing import Dict, Optional
from src.utils.token_tracker import record_agent_usage


class MAVLinkCommandSender:
    """Sends MAVLink commands to drone with proper formatting."""

    # MAVLink command constants
    MAV_CMD_COMPONENT_ARM_DISARM = 400
    MAV_CMD_NAV_TAKEOFF = 22
    MAV_CMD_NAV_LAND = 21
    MAV_CMD_NAV_RETURN_TO_LAUNCH = 20
    MAV_CMD_DO_SET_MODE = 176

    # Flight modes
    FLIGHT_MODES = {
        'STABILIZE': 0,
        'ACRO': 1,
        'ALT_HOLD': 2,
        'AUTO': 3,
        'GUIDED': 4,
        'LOITER': 5,
        'RTL': 6,
        'CIRCLE': 7,
        'LAND': 9,
        'BRAKE': 17
    }

    def __init__(self, target_system: int = 1, target_component: int = 1):
        """Initialize command sender."""
        self.target_system = target_system
        self.target_component = target_component
        self.command_sequence = 0

        record_agent_usage('mavlink-protocol-agent', 40, 30)

    def send_command(self, command: int, param1: float = 0, param2: float = 0,
                    param3: float = 0, param4: float = 0, param5: float = 0,
                    param6: float = 0, param7: float = 0) -> Dict:
        """Send generic MAVLink command."""
        self.command_sequence += 1

        command_dict = {
            'command': command,
            'target_system': self.target_system,
            'target_component': self.target_component,
            'confirmation': 0,
            'param1': param1,
            'param2': param2,
            'param3': param3,
            'param4': param4,
            'param5': param5,
            'param6': param6,
            'param7': param7,
            'sequence': self.command_sequence,
            'timestamp': time.time()
        }

        record_agent_usage('mavlink-protocol-agent', 25, 20)
        return command_dict

    def send_arm_command(self, force_arm: bool = False, confirmed: bool = False) -> Dict:
        """Send ARM command to drone with safety validation."""
        if not confirmed:
            return {
                'success': False,
                'message': 'ARM command requires explicit confirmation for safety',
                'ack_received': False
            }

        param1 = 1  # ARM
        param2 = 21196 if force_arm else 0  # Force ARM magic number

        command_dict = self.send_command(
            self.MAV_CMD_COMPONENT_ARM_DISARM,
            param1=param1,
            param2=param2
        )

        # Simulate sending and acknowledgment
        return self._send_mavlink_command('COMPONENT_ARM_DISARM', command_dict)

    def send_disarm_command(self, force_disarm: bool = False, confirmed: bool = False) -> Dict:
        """Send DISARM command to drone with safety validation."""
        if not confirmed:
            return {
                'success': False,
                'message': 'DISARM command requires explicit confirmation for safety',
                'ack_received': False
            }

        param1 = 0  # DISARM
        param2 = 21196 if force_disarm else 0  # Force DISARM magic number

        command_dict = self.send_command(
            self.MAV_CMD_COMPONENT_ARM_DISARM,
            param1=param1,
            param2=param2
        )

        # Simulate sending and acknowledgment
        return self._send_mavlink_command('COMPONENT_ARM_DISARM', command_dict)

    def send_takeoff_command(self, altitude: float, pitch: float = 0,
                           yaw: float = float('nan'), confirmed: bool = False) -> Dict:
        """Send TAKEOFF command with altitude validation and safety confirmation."""
        if not confirmed:
            return {
                'success': False,
                'message': 'TAKEOFF command requires explicit confirmation for safety',
                'ack_received': False
            }

        # Validate altitude
        if altitude <= 0:
            return {
                'success': False,
                'message': 'TAKEOFF altitude must be positive',
                'ack_received': False
            }

        if altitude > 100:  # 100m max for safety
            return {
                'success': False,
                'message': 'TAKEOFF altitude exceeds maximum safe limit (100m)',
                'ack_received': False
            }

        command_dict = self.send_command(
            self.MAV_CMD_NAV_TAKEOFF,
            param1=pitch,     # Minimum pitch
            param4=yaw,       # Yaw angle
            param7=altitude   # Altitude
        )

        # Simulate sending and acknowledgment
        return self._send_mavlink_command('NAV_TAKEOFF', command_dict)

    def send_land_command(self, yaw: float = float('nan'),
                         lat: float = 0, lon: float = 0, alt: float = 0) -> Dict:
        """Send LAND command."""
        return self.send_command(
            self.MAV_CMD_NAV_LAND,
            param4=yaw,  # Yaw angle
            param5=lat,  # Latitude
            param6=lon,  # Longitude
            param7=alt   # Altitude
        )

    def send_rtl_command(self) -> Dict:
        """Send Return to Launch command."""
        return self.send_command(self.MAV_CMD_NAV_RETURN_TO_LAUNCH)

    def send_set_mode_command(self, mode: str) -> Dict:
        """Send SET_MODE command."""
        mode_number = self.FLIGHT_MODES.get(mode.upper(), 4)  # Default to GUIDED

        return self.send_command(
            self.MAV_CMD_DO_SET_MODE,
            param1=1,           # MAV_MODE_FLAG_CUSTOM_MODE_ENABLED
            param2=mode_number  # Custom mode number
        )

    def send_goto_command(self, latitude: float, longitude: float, altitude: float, confirmed: bool = False) -> Dict:
        """Send GOTO position command with input validation."""
        if not confirmed:
            return {
                'success': False,
                'message': 'GOTO command requires explicit confirmation for safety',
                'ack_received': False
            }

        # Validate coordinates
        if not isinstance(latitude, (int, float)) or not isinstance(longitude, (int, float)):
            return {
                'success': False,
                'message': 'Invalid coordinate format - must be numeric',
                'ack_received': False
            }

        if latitude is None or longitude is None:
            return {
                'success': False,
                'message': 'Invalid coordinates - None values not allowed',
                'ack_received': False
            }

        if latitude < -90 or latitude > 90:
            return {
                'success': False,
                'message': 'Invalid latitude - must be between -90 and 90 degrees',
                'ack_received': False
            }

        if longitude < -180 or longitude > 180:
            return {
                'success': False,
                'message': 'Invalid longitude - must be between -180 and 180 degrees',
                'ack_received': False
            }

        command_dict = self.send_command(
            16,  # MAV_CMD_NAV_WAYPOINT
            param1=0,    # Hold time
            param2=0,    # Accept radius
            param3=0,    # Pass radius
            param4=float('nan'),  # Yaw
            param5=latitude,  # Latitude
            param6=longitude,  # Longitude
            param7=altitude   # Altitude
        )

        return self._send_mavlink_command('NAV_WAYPOINT', command_dict)

    def get_sender_info(self) -> Dict:
        """Get command sender information."""
        return {
            'target_system': self.target_system,
            'target_component': self.target_component,
            'command_sequence': self.command_sequence,
            'available_modes': list(self.FLIGHT_MODES.keys())
        }

