def connect(self, host: str = None, port: int = None):
    """Establish MAVLink connection to drone."""
    # Use provided host/port or defaults
    target_host = host or self.host
    target_port = port or self.port

    with self._lock:
        try:
            # Update connection parameters if provided
            if host:
                self.host = host
            if port:
                self.port = port

            # First check if endpoint is reachable
            if not self._test_tcp_connection():
                return {
                    'success': False,
                    'message': f'Cannot reach {target_host}:{target_port}',
                    'host': target_host,
                    'port': target_port
                }

            # Create MAVLink connection string
            connection_string = f"tcp:{target_host}:{target_port}"

            # Establish MAVLink connection with timeout
            self.connection = mavutil.mavlink_connection(
                connection_string,
                timeout=self.timeout
            )

            if self.connection:
                # Wait for first message to confirm connection
                start_time = time.time()
                while (time.time() - start_time) < self.timeout:
                    msg = self.connection.recv_match(blocking=False)
                    if msg:
                        if msg.get_type() == 'HEARTBEAT':
                            self.system_id = msg.get_srcSystem()
                            self.component_id = msg.get_srcComponent()
                            self.connected = True
                            record_agent_usage('mavlink-protocol-agent', 40, 25)
                            return {
                                'success': True,
                                'message': f'Connected to drone at {target_host}:{target_port}',
                                'host': target_host,
                                'port': target_port,
                                'system_id': self.system_id,
                                'component_id': self.component_id
                            }
                    time.sleep(0.1)

            return {
                'success': False,
                'message': f'No heartbeat received from {target_host}:{target_port}',
                'host': target_host,
                'port': target_port
            }

        except Exception as e:
            self.connected = False
            record_agent_usage('mavlink-protocol-agent', 20, 15)
            return {
                'success': False,
                'message': f'Connection error: {str(e)}',
                'host': target_host,
                'port': target_port
            }

